description: Quy tắc chung khi viết code Three.js trong src/
---

# Code Three.js trong `src/`

- **Seed:** không thêm/bớt/đổi thứ tự lời gọi `rand()` (`common/math.ts`). Ngẫu nhiên mới → `const r = rng(<seed riêng>)`.
- **Thông số:** không hard-code số đo trong file dựng hình. Đặt ở `src/config.ts` (chú thích tiếng Việt, đơn vị, `(ước lượng)`), đọc qua `CONFIG.<khối>` hoặc `profile.ts`.
- **Draw call:**
  - Bộ phận tĩnh cùng vật liệu → đẩy vào `concreteParts`/`steelParts` hoặc gộp bằng `mergeGeometries`.
  - Vật lặp lại → `InstancedMesh`; ẩn instance bằng ma trận scale 0.
  - Chi tiết nhỏ → `details` (LOD) hoặc `farHide`; không cần phản chiếu → `noReflect` / `layers.set(1)`.
- **Vật liệu:** tái dùng `MAT` (`core/materials.ts`) khi có thể; vật liệu riêng tạo trong `materials.ts` của công trình và dispose được.
- **Ngày/đêm:** đọc `shared.uNight`; đèn bằng emissive/shader, không thêm `PointLight`/`SpotLight`.
- **Texture:** phần cảnh dựng bằng code vẽ texture bằng canvas (`common/textures.ts`, `core/textures.ts`). Mô hình ngoài và texture đi kèm được phép theo D-033 (`copilot-instructions.md` §3 mục 5): giấy phép, ghi nguồn, trần dung lượng có test, đường lùi khi tải lỗi.
- **Hệ trục:** X Tây→Đông, −Z Bắc, mét; y = 0 mặt nước.
- **Dispose:** mọi geometry/material/`CanvasTexture` tự tạo phải giải phóng được (theo `BridgeBase.dispose()`).
- Comment tiếng Việt; khối tiêu đề `/* ===== ... ===== */` mô tả công trình/vị trí ở đầu file chính.
- Sau khi sửa: `npm run typecheck`.
- **Đèn (D-031):** không đặt `visible` của đèn ngoài `core/lights.ts`; cường độ ghi trước `stepLights()` trong `animate()`. Đèn cường độ 0 vẫn tốn shader mọi điểm ảnh.
- **Lưới nặng có đổ bóng / phản chiếu:** cân nhắc bản thưa qua `core/passLod.ts` thay vì vẽ đủ chi tiết ở cả ba lượt (bóng, phản chiếu, chính).
- **Người đi bộ thật (D-032, `src/common/people/crowd*.ts`):** mỗi hệ một `THREE.BatchedMesh` (r165), mỗi người một `addGeometry`; phải `setColorAt` cho mọi id; chỉ dựng khi `crowdUsable(crowdGet(), có WEBGL_multi_draw)`, thiếu `WEBGL_multi_draw` thì r165 vẽ mỗi người một lệnh nên phải dùng hình khối cũ. Chọn nhân vật bằng băm chỉ số, không `rand()` / `rng`. Ẩn người bằng `setVisibleAt`. Mọi lưới / vật liệu / texture tạo lúc dựng; texture trong uniform phải `renderer.initTexture`. Làm nóng `BatchedMesh` phải qua `bmUncull` trong `core/prewarm.ts` (tạm tắt `perObjectFrustumCulled` và đặt `_visibilityChanged`), nếu không mọi id bị cắt thì three bỏ lệnh vẽ. Vật liệu hình khối `peopleWalk` vẫn cần trong cảnh cho hình tạm của Đi dạo (`stBlocky`). Chi tiết: `systemPatterns.md` mục "Mẫu đám đông người thật".
- Chế độ Lái xe (D-034, `src/explore/drive/`): mặt đường mới, dải giữa / vỉa đã cắt đoạn, vật cản đọc từ cảnh qua `drCollectRuntime` (một lần mỗi `net`). Thêm / dời / xóa công trình, nhà, đường thì xem lại `driveRoadGeo.ts` (bảng mặt cắt chép tay), `roadData.ts`, `drClearRoads` (dọn nhà / cây trên đường mới, dựng SAU mọi `rand()`) và `test:drive:unit`; xe người chơi dùng số thật của VF 3 (`CONFIG.drive`), không bóp mô hình để vừa đường. Xem `systemPatterns.md` mục "Mẫu chế độ lái xe".
import * as THREE from 'three';
import { CONFIG } from '../config';
import { scene } from '../core/renderer';
import { rand, clamp } from '../common/math';
import { patchWindows, patchFarGlow } from '../common/shaders';

/* ============================ Đô thị ============================ */
export function buildCity() {
  const items: { x: number; z: number; w: number; d: number; h: number; c: number }[] = [];
  const palette = [0xf3f0e7, 0xeae2cf, 0xdadcdc, 0xcfe0e7, 0xdde8df, 0xc8ced4, 0xf6f6f2, 0xe6dccb];
  const avoid = (_x: number, z: number) => Math.abs(z) < 48 || Math.abs(z - CONFIG.ttl.z) < 40;
  const place = (x0: number, x1: number, near: number, beach: boolean) => {
    const step = 36;
    for (let gx = x0; gx < x1; gx += step) for (let gz = -1800; gz < 1800; gz += step) {
      const ix = Math.round(gx / step), iz = Math.round(gz / step);
      if (ix % 5 === 0 || iz % 5 === 0) continue;  // chừa đường phố
      if (avoid(gx, gz) || rand() < 0.16) continue;
      const nearR = 1 - clamp((Math.abs(gx - near)) / 900, 0, 1);
      let h = 9 + rand() * 26 + nearR * rand() * 65 + (rand() < 0.05 ? 55 : 0);
      if (beach && gx > 1290) h = 45 + rand() * 115; // khách sạn ven biển Mỹ Khê
      items.push({ x: gx + (rand() - 0.5) * 6, z: gz + (rand() - 0.5) * 6, w: 14 + rand() * 15, d: 14 + rand() * 15, h, c: palette[Math.floor(rand() * palette.length)] });
    }
  };
  place(-2000, -330, -330, false); // bờ Tây — trung tâm Hải Châu
  place(340, 1450, 340, true);      // bờ Đông — Sơn Trà
  // Gom thành cụm, mỗi cụm là một LOD (gần: có cửa sổ; xa: khối trơn)
  const cell = 900, clusters = new Map<string, typeof items>();
  for (const b of items) { const key = `${Math.floor(b.x / cell)}_${Math.floor(b.z / cell)}`; if (!clusters.has(key)) clusters.set(key, []); clusters.get(key).push(b); }
  const geo = new THREE.BoxGeometry(1, 1, 1).translate(0, 0.5, 0);
  const nearMat = new THREE.MeshStandardMaterial({ color: 0xffffff, roughness: 0.75, metalness: 0.05 });
  patchWindows(nearMat, { perBuilding: true });
  const farMat = new THREE.MeshStandardMaterial({ color: 0xffffff, roughness: 0.9 });
  patchFarGlow(farMat);
  const m = new THREE.Matrix4(), q = new THREE.Quaternion(), v = new THREE.Vector3(), s = new THREE.Vector3(), col = new THREE.Color();
  for (const list of clusters.values()) {
    const cx = list.reduce((a, b) => a + b.x, 0) / list.length, cz = list.reduce((a, b) => a + b.z, 0) / list.length;
    const near = new THREE.InstancedMesh(geo, nearMat, list.length), far = new THREE.InstancedMesh(geo, farMat, list.length);
    list.forEach((b, i) => {
      m.compose(v.set(b.x - cx, CONFIG.landY, b.z - cz), q, s.set(b.w, b.h, b.d));
      near.setMatrixAt(i, m); far.setMatrixAt(i, m); col.setHex(b.c); near.setColorAt(i, col); far.setColorAt(i, col.multiplyScalar(0.92));
    });
    near.castShadow = true; near.receiveShadow = true;
    const lod = new THREE.LOD(); lod.position.set(cx, 0, cz);
    lod.addLevel(near, 0); lod.addLevel(far, 2200); lod.addLevel(new THREE.Object3D(), 8000);
    scene.add(lod);
  }
}
import * as THREE from 'three';
import { scene } from '../../core/renderer';
import { MAT } from '../../core/materials';

/* [clearance] Dọn nhà, cây, cột đèn ngẫu nhiên đè lên công trình mới mà KHÔNG đụng tới chuỗi rand() của khu phố:
   sau khi cảnh đã dựng, gán ma trận scale 0 cho instance bị đè (cả level near lẫn far của LOD nhà), giống corridor.ts của hầm. */
export interface Rect { x0: number; x1: number; z0: number; z1: number }
export interface Building { mesh: THREE.InstancedMesh; i: number; x: number; z: number; w: number; d: number; h: number }

const plants = () => new Set<THREE.Material>([MAT.trunk, MAT.leaf, MAT.palm, MAT.lampPole, MAT.bulb]);
const _m = new THREE.Matrix4(), _p = new THREE.Vector3(), _q = new THREE.Quaternion(), _s = new THREE.Vector3(), _zero = new THREE.Matrix4().makeScale(0, 0, 0);

/* Các InstancedMesh nhà (con của THREE.LOD do buildCity dựng); level 0 là bản gần có cửa sổ */
function buildingMeshes() {
  const out: { mesh: THREE.InstancedMesh; near: boolean }[] = [];
  scene.traverse((o) => {
    const m = o as THREE.InstancedMesh;
    if (m.isInstancedMesh && m.parent && (m.parent as THREE.LOD).isLOD) out.push({ mesh: m, near: (m.parent as THREE.LOD).levels[0]?.object === m });
  });
  return out;
}
/* Nhà đang hiện (scale > 0) ở level near, tọa độ thế giới */
export function collectBuildings(): Building[] {
  scene.updateMatrixWorld(true);
  const list: Building[] = [];
  for (const { mesh, near } of buildingMeshes()) {
    if (!near) continue;
    for (let i = 0; i < mesh.count; i++) {
      mesh.getMatrixAt(i, _m); _m.decompose(_p, _q, _s);
      if (_s.x < 1e-6) continue;
      _p.applyMatrix4(mesh.matrixWorld);
      list.push({ mesh, i, x: _p.x, z: _p.z, w: _s.x, d: _s.z, h: _s.y });
    }
  }
  return list;
}
/* Ảnh chụp ma trận nhà ngay trước khi dọn, để kiểm tra "nhà không bị dọn giữ nguyên ma trận" */
export const snapshot = new Map<THREE.InstancedMesh, Float32Array>();

export function clearRects(rects: Rect[], margin: number) {
  scene.updateMatrixWorld(true);
  const pl = plants(); let nb = 0, np = 0;
  const hit = (x: number, z: number, hw: number, hd: number) => rects.some((r) => x + hw > r.x0 - margin && x - hw < r.x1 + margin && z + hd > r.z0 - margin && z - hd < r.z1 + margin);
  scene.traverse((obj) => {
    const o = obj as THREE.InstancedMesh;
    if (!o.isInstancedMesh) return;
    const building = !!o.parent && (o.parent as THREE.LOD).isLOD;
    if (!building && !pl.has(o.material as THREE.Material)) return;
    if (building && !snapshot.has(o)) snapshot.set(o, (o.instanceMatrix.array as Float32Array).slice());
    let changed = false;
    for (let i = 0; i < o.count; i++) {
      o.getMatrixAt(i, _m); _m.decompose(_p, _q, _s);
      if (_s.x < 1e-6) continue;
      _p.applyMatrix4(o.matrixWorld);
      if (hit(_p.x, _p.z, building ? _s.x / 2 : 1.5, building ? _s.z / 2 : 1.5)) { o.setMatrixAt(i, _zero); changed = true; building ? nb++ : np++; }
    }
    if (changed) o.instanceMatrix.needsUpdate = true;
  });
  return { buildings: nb, plants: np };
}

