const R = 'file:///D:/2026%20-%20Tuan/danang-vite/';
const { chromium } = await import(R + 'node_modules/playwright/index.mjs');
const { serveDir, openApp, frames } = await import(R + 'tests/lib.mjs');
const srv = await serveDir('D:/2026 - Tuan/danang-vite/dist/');
const browser = await chromium.launch({ headless: true, args: ['--use-angle=d3d11', '--ignore-gpu-blocklist', '--enable-gpu', '--disable-gpu-vsync', '--disable-frame-rate-limit'] });
const CAMS = { 'tren-cao': [[-430, 330, 560], [0, 12, 0]], 'nha-mau': [[-200, 40, 20], [-400, 25, -150]] };
for (const run of ['A', 'B', 'A', 'B']) {
  const { page } = await openApp(browser, srv.url + '?perf' + (run === 'A' ? '&buildings=off' : ''), { width: 1600, height: 900 });
  const line = [];
  for (const [n, [pos, tgt]] of Object.entries(CAMS)) {
    await page.evaluate(([p, t]) => { const A = window.__app; A.cam.mode = 'orbit'; A.controls.enabled = true; A.camera.position.set(...p); A.controls.target.set(...t); A.controls.update(); }, [pos, tgt]);
    await frames(page, 6);
    const g = await page.evaluate(async () => {
      const A = window.__app, R = A.renderer, gl = R.getContext(), ext = gl.getExtension('EXT_disjoint_timer_query_webgl2');
      const sleep = (ms) => new Promise((ok) => setTimeout(ok, ms)), draw = () => R.render(A.scene, A.camera);
      const a = [];
      for (let j = 0; j < 7; j++) { draw(); draw(); const q = gl.createQuery(); gl.beginQuery(ext.TIME_ELAPSED_EXT, q); for (let i = 0; i < 12; i++) draw(); gl.endQuery(ext.TIME_ELAPSED_EXT); gl.flush();
        for (let k = 0; k < 400; k++) { await sleep(5); if (gl.getQueryParameter(q, gl.QUERY_RESULT_AVAILABLE)) break; } a.push(gl.getQueryParameter(q, gl.QUERY_RESULT) / 1e6 / 12); gl.deleteQuery(q); }
      a.sort((x, y) => x - y); return a[3];
    });
    line.push(`${n} ${g.toFixed(2)} ms`);
  }
  console.log(run === 'A' ? 'A (buildings=off)' : 'B (kit)         ', line.join(' · '));
  await page.close();
}
await browser.close(); srv.close();
